#!/usr/bin/env bash
set -euo pipefail

# Throwaway client pod that mounts the root client cert generated by the chart
IMAGE=$(kubectl get statefulset crdb-cockroachdb -o jsonpath='{.spec.template.spec.containers[0].image}')
trap 'kubectl delete pod crdb-client --ignore-not-found' EXIT

kubectl apply -f - <<YAML
apiVersion: v1
kind: Pod
metadata:
  name: crdb-client
spec:
  restartPolicy: Never
  containers:
    - name: client
      image: ${IMAGE}
      command: ["sleep", "3600"]
      volumeMounts:
        - {name: certs, mountPath: /certs}
  volumes:
    - name: certs
      secret:
        secretName: crdb-cockroachdb-client-secret
        defaultMode: 256   # 0400, cockroach rejects looser key permissions
        items:
          - {key: ca.crt, path: ca.crt}
          - {key: tls.crt, path: client.root.crt}
          - {key: tls.key, path: client.root.key}
YAML
kubectl wait --for=condition=Ready pod/crdb-client --timeout=120s

SQL="/cockroach/cockroach sql --certs-dir=/certs --host=crdb-cockroachdb-public"
kubectl exec crdb-client -- /cockroach/cockroach node status --certs-dir=/certs --host=crdb-cockroachdb-public
kubectl exec crdb-client -- $SQL \
  -e "CREATE TABLE smoke (i INT); INSERT INTO smoke VALUES (1); SELECT * FROM smoke; DROP TABLE smoke;"